import{_ as r,o as d,c as e,a2 as a}from"./chunks/framework.BWuWLRhz.js";const c=JSON.parse('{"title":"지원되는 파일 관리자","description":"","frontmatter":{},"headers":[],"relativePath":"ko-KR/user-guide/file-manager-support.md","filePath":"ko-KR/user-guide/file-manager-support.md","lastUpdated":1787015899000}'),o={name:"ko-KR/user-guide/file-manager-support.md"};function s(i,t,n,h,l,p){return d(),e("div",null,[...t[0]||(t[0]=[a('<h1 id="지원되는-파일-관리자" tabindex="-1">지원되는 파일 관리자 <a class="header-anchor" href="#지원되는-파일-관리자" aria-label="Permalink to &quot;지원되는 파일 관리자&quot;">​</a></h1><p>Lertaro는 검색만 하는 것이 아니라, 현재 사용 중인 파일 관리자나 대화상자와도 통합될 수 있습니다. 대상에 따라 이 통합은 최대 세 가지를 의미할 수 있습니다.</p><ul><li><strong>인라인 검색 도킹</strong> — Lertaro 검색창이 대상 창(<a href="./getting-started.html#세-가지-창">인라인 창</a>) 안에 직접 내장되어, 그곳을 벗어나지 않고도 검색할 수 있습니다.</li><li><strong>빠른 탐색(Quick Navigation)</strong> — 대상이 <a href="./hotkeys.html#빠른-탐색-마우스">빠른 탐색 마우스 트리거</a>(더블클릭/미들클릭, 또는 인라인 창 자체의 로고)에 반응하여 즐겨찾기, 기록, 빠른 접근 폴더의 계단식 메뉴를 띄웁니다.</li><li><strong>활성 경로 감지</strong> — Lertaro가 대상에서 현재 열려 있는 폴더가 어디인지 파악하여, 검색 범위를 그 폴더로 한정하고 (경로 복사 같은) 경로 상대적 동작을 그 폴더 기준으로 해석할 수 있습니다.</li></ul><p>모든 통합이 세 가지를 다 제공하는 것은 아닙니다 — 아래 표를 참고하세요.</p><h2 id="빠른-탐색의-열려-있는-폴더" tabindex="-1">빠른 탐색의 열려 있는 폴더 <a class="header-anchor" href="#빠른-탐색의-열려-있는-폴더" aria-label="Permalink to &quot;빠른 탐색의 열려 있는 폴더&quot;">​</a></h2><p>Folder Cascader 플러그인에서 <strong>열려 있는 폴더 표시</strong>를 켜면(기본값: 켜짐), 빠른 탐색에 즐겨찾기와 기록보다 앞선 <strong>열려 있는 폴더</strong> 그룹이 추가됩니다. 지원되는 모든 파일 관리자에서 현재 열려 있는 실제 파일 시스템 폴더를 모으고 중복 경로는 자동으로 제거합니다. 가상 위치와 더 이상 존재하지 않는 폴더는 표시하지 않으므로 목록의 모든 항목으로 정상적으로 이동할 수 있습니다.</p><h2 id="내장-지원-추가-설치-불필요" tabindex="-1">내장 지원 (추가 설치 불필요) <a class="header-anchor" href="#내장-지원-추가-설치-불필요" aria-label="Permalink to &quot;내장 지원 (추가 설치 불필요)&quot;">​</a></h2><p>이들은 Lertaro의 핵심 확장 플러그인에 번들되어 있습니다 — 별도로 활성화할 것이 없습니다.</p><table tabindex="0"><thead><tr><th>대상</th><th>인라인 검색 도킹</th><th>빠른 탐색</th><th>활성 경로 감지</th></tr></thead><tbody><tr><td>Windows 파일 탐색기</td><td>지원</td><td>더블클릭 또는 미들클릭</td><td>지원</td></tr><tr><td>최신 열기/저장 파일 대화상자</td><td>지원 (이 자체가 인라인 창입니다)</td><td>미들클릭, 또는 인라인 창 자체의 로고 좌클릭</td><td>—</td></tr><tr><td>클래식 열기/저장 파일 대화상자</td><td>지원</td><td>미들클릭, 또는 인라인 창 자체의 로고 좌클릭</td><td>—</td></tr><tr><td>클래식 폴더 찾아보기 대화상자</td><td>지원</td><td>미들클릭, 또는 인라인 창 자체의 로고 좌클릭</td><td>—</td></tr></tbody></table><p>활성 경로 감지는 대화상자 자체에는 적용되지 않습니다 — 이미 대화상자 안에 도킹된 상태에서는 Lertaro가 검색 범위를 한정할 &quot;다른 창&quot;이 존재하지 않기 때문입니다.</p><h2 id="선택적-플러그인-설정-→-플러그인" tabindex="-1">선택적 플러그인 (설정 → 플러그인) <a class="header-anchor" href="#선택적-플러그인-설정-→-플러그인" aria-label="Permalink to &quot;선택적 플러그인 (설정 → 플러그인)&quot;">​</a></h2><p>다음 각각은 자체 플러그인으로 제공됩니다. <a href="./settings/plugins.html">설정 → 플러그인</a>에서 설치/활성화한 뒤, 해당 플러그인 자체의 <strong>구성</strong> 대화상자에서 <strong>인라인 검색 활성화</strong>와 <strong>빠른 탐색 활성화</strong>를 각각 독립적으로 켜고 끌 수 있습니다 — 둘 다 기본값은 켜짐입니다.</p><table tabindex="0"><thead><tr><th>대상</th><th>인라인 검색 도킹</th><th>빠른 탐색</th><th>활성 경로 감지</th></tr></thead><tbody><tr><td>Directory Opus</td><td>지원</td><td>파일 목록 패널에서 미들클릭</td><td>지원</td></tr><tr><td>Files</td><td>지원</td><td>파일 목록 패널에서 미들클릭</td><td>지원</td></tr><tr><td>One Commander</td><td>지원</td><td>파일 목록 패널에서 미들클릭</td><td>지원</td></tr><tr><td>Total Commander</td><td>지원</td><td>파일 목록 패널에서 미들클릭</td><td>지원</td></tr><tr><td>XYplorer</td><td>지원</td><td>파일 목록 패널에서 미들클릭</td><td>지원</td></tr></tbody></table><p>다섯 개 모두 실행 중인 프로세스를 매칭하여 대상을 감지합니다(Directory Opus와 Total Commander의 경우, UI를 긁어오는 대신 각자가 문서화한 원격 제어 인터페이스와 <code>WM_COPYDATA</code>로 통신합니다). Files와 One Commander는 원격 제어 프로토콜을 노출하지 않으므로 대신 UI 자동화를 사용합니다.</p><h2 id="directory-opus의-인덱싱된-폴더-크기" tabindex="-1">Directory Opus의 인덱싱된 폴더 크기 <a class="header-anchor" href="#directory-opus의-인덱싱된-폴더-크기" aria-label="Permalink to &quot;Directory Opus의 인덱싱된 폴더 크기&quot;">​</a></h2><p>Directory Opus 플러그인의 <strong>Lertaro 크기 열 사용</strong> 옵션을 켜면(기본값: 켜짐) Lertaro가 Directory Opus에 <strong>Lertaro Size</strong> 스크립트 열을 설치합니다. 이 열은 Lertaro가 현재 메모리에 보유한 인덱스에서 각 인덱싱된 폴더의 재귀 크기를 표시하며, 디스크를 검사하지 않습니다. 파일 행은 계속 Directory Opus의 기본 크기 열을 사용하고, Lertaro가 인덱싱하지 않은 폴더에는 이 열의 값이 비어 있습니다. 이 옵션을 끄면 Lertaro는 스크립트를 더 이상 쓰거나 업데이트하지 않으며, 이미 설치된 스크립트는 의도적으로 남겨 둡니다.</p><p>Directory Opus의 열 선택기에서 <strong>Lertaro Size</strong>를 추가하세요. 폴더 전환이나 Directory Opus 재시작 뒤에도 열을 유지하려면 <strong>Folder → Folder Format → Save → Save format for all folders</strong>를 사용하세요. 로컬 드라이브나 네트워크 드라이브용처럼 더 구체적인 Folder Format은 사용자 기본 형식보다 우선하므로, 필요한 경우 해당 형식에도 이 열을 추가해야 합니다.</p><h2 id="애플리케이션-자체-대화상자-선택적-플러그인" tabindex="-1">애플리케이션 자체 대화상자 (선택적 플러그인) <a class="header-anchor" href="#애플리케이션-자체-대화상자-선택적-플러그인" aria-label="Permalink to &quot;애플리케이션 자체 대화상자 (선택적 플러그인)&quot;">​</a></h2><p>이들은 애플리케이션 전체가 아니라, 타사 애플리케이션 안의 특정 대화상자 하나를 대상으로 합니다 — 위의 내장 대화상자와 같은 방식입니다. <a href="./settings/plugins.html">설정 → 플러그인</a>에서 설치/활성화하며, 각각 자체적인 켜기/끄기 스위치가 있는 단일 컴포넌트로 제공됩니다(전환할 것이 하나뿐이므로 별도의 구성 대화상자는 없습니다).</p><table tabindex="0"><thead><tr><th>대상</th><th>인라인 검색 도킹</th><th>빠른 탐색</th><th>활성 경로 감지</th></tr></thead><tbody><tr><td>WPS Office의 열기/저장 대화상자</td><td>지원</td><td>미들클릭, 또는 인라인 창 자체의 로고 좌클릭</td><td>—</td></tr><tr><td>WinRAR의 압축 풀기 대화상자</td><td>지원</td><td>미들클릭, 또는 인라인 창 자체의 로고 좌클릭</td><td>—</td></tr><tr><td>Bandizip의 압축 풀기 대화상자</td><td>지원</td><td>미들클릭, 또는 인라인 창 자체의 로고 좌클릭</td><td>—</td></tr><tr><td>Bandizip의 파일 추가 대화상자</td><td>지원</td><td>미들클릭, 또는 인라인 창 자체의 로고 좌클릭</td><td>—</td></tr></tbody></table><p>창 제목이 아니라 컨트롤 구조로 감지하므로, 각 애플리케이션이 제공하는 모든 언어 팩에서 동작합니다. WPS 항목은 문서, 스프레드시트, 프레젠테이션, PDF 리더를 모두 포함하며 이들은 같은 대화상자를 사용합니다. WPS는 Windows 기본 대화상자가 아닌 자체 대화상자를 쓰기 때문에 별도의 플러그인이 필요하며, 대부분의 애플리케이션이 위의 내장 대화상자로 처리되는 것과 대비됩니다. 그것들과 마찬가지로 활성 경로 감지는 적용되지 않습니다 — Lertaro가 이미 대화상자 자체 안에 도킹되어 있어, 검색 범위를 한정할 다른 창이 없기 때문입니다.</p><hr><p>여기 목록에 없는 파일 관리자를 위한 자체 통합을 만들고 계신가요? 개발자 매뉴얼의 <a href="./../dev-guide/sdk/system-adapters.html">시스템 및 대화상자 어댑터</a> 참조를 확인하세요.</p>',23)])])}const g=r(o,[["render",s]]);export{c as __pageData,g as default};
